  INSERT INTO public.matching_games (lesson_id, title, description)
  SELECT 'bc182063-a10e-4bc4-b072-34dec460253b'::uuid, 'Match: Legacy and Revival', 'Match the terms with their meanings'
  WHERE NOT EXISTS (SELECT 1 FROM public.matching_games WHERE lesson_id = 'bc182063-a10e-4bc4-b072-34dec460253b')
  RETURNING id
)
INSERT INTO public.matching_pairs (game_id, left_item, right_item, order_index)
SELECT g.id, p.l, p.r, p.idx FROM new_game g, (VALUES
  ('Cultural DNA', 'Embedded heritage', 0),
  ('Post-1991 revival', 'Public return', 1),
  ('Gadaa UNESCO 2016', 'International recognition', 2),
  ('Knowledge loss risk', 'Elder transmission concern', 3),
  ('Ritual site protection', 'Sacred spaces threatened', 4),
  ('Ethnographic research', 'Documentation', 5),
  ('Youth program', 'Transmission effort', 6),
  ('Legitimate monotheism', 'Scholarly framing', 7),
  ('Not paganism/animism', 'Dismissive labels rejected', 8),
  ('Shared inheritance', 'For all Oromo', 9)
) AS p(l, r, idx);

COMMIT;

